import { useCallback, useEffect, useRef } from 'react';

import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import { swrKeys } from '@onekeyhq/shared/src/utils/swrCacheUtils';
import type { IBorrowMarketItem } from '@onekeyhq/shared/types/staking';

import { usePromiseResult } from '../../../hooks/usePromiseResult';

const BORROW_POLLING_INTERVAL = 3 * 60 * 1000;
const defaultMarkets: IBorrowMarketItem[] = [];

export const useBorrowMarkets = ({
  isActive = true,
}: { isActive?: boolean } = {}) => {
  const isActiveRef = useRef(isActive);
  const marketsRef = useRef<typeof defaultMarkets>(defaultMarkets);
  const lastUpdatedAtRef = useRef<number | null>(null);

  useEffect(() => {
    isActiveRef.current = isActive;
  }, [isActive]);

  const {
    result: markets,
    isLoading = true,
    run: runFetchMarkets,
  } = usePromiseResult(
    async () => {
      const cached = marketsRef.current ?? defaultMarkets;
      if (!isActiveRef.current) {
        return cached;
      }
      const lastUpdatedAt = lastUpdatedAtRef.current;
      const isStale =
        !lastUpdatedAt || Date.now() - lastUpdatedAt > BORROW_POLLING_INTERVAL;
      if (!isStale) {
        return cached;
      }
      const result = await backgroundApiProxy.serviceStaking.getBorrowMarkets();
      marketsRef.current = result;
      lastUpdatedAtRef.current = Date.now();
      return result;
    },
    [],
    {
      initResult: defaultMarkets,
      swrKey: swrKeys.borrowMarkets(),
      swrShouldPersist: (result) => result.length > 0,
      watchLoading: true,
      checkIsFocused: true,
      undefinedResultIfReRun: false,
      pollingInterval: isActive ? BORROW_POLLING_INTERVAL : undefined,
      revalidateOnFocus: false,
    },
  );

  // usePromiseResult starts its request effect before effects declared below.
  // Mirror a synchronously hydrated SWR result during render so an inactive
  // first run returns that snapshot instead of overwriting it with [].
  if (markets) {
    marketsRef.current = markets;
  }

  const refetchMarkets = useCallback(async () => {
    lastUpdatedAtRef.current = null;
    await runFetchMarkets({ alwaysSetState: true });
  }, [runFetchMarkets]);

  return { markets, isLoading, refetchMarkets };
};
